create extension if not exists "pgcrypto";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, discord text, role text not null default 'customer' check(role in ('customer','admin')), created_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, created_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id) on delete set null, name text not null, slug text not null unique, description text, price numeric(10,2) not null check(price>=0), old_price numeric(10,2), image_url text, active boolean not null default true, automatic_delivery boolean not null default false, delivery_instructions text, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), status text not null default 'pending' check(status in ('pending','paid','processing','delivered','cancelled')), total numeric(10,2) not null check(total>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, unit_price numeric(10,2) not null, quantity integer not null default 1 check(quantity>0));
create table public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, provider text not null, provider_payment_id text, status text not null default 'pending', amount numeric(10,2) not null, paid_at timestamptz, created_at timestamptz not null default now());
create table public.digital_deliveries (id uuid primary key default gen_random_uuid(), order_item_id uuid not null references public.order_items(id) on delete cascade, user_id uuid not null references auth.users(id), delivery_content text, delivered_at timestamptz, created_at timestamptz not null default now());
create table public.coupons (id uuid primary key default gen_random_uuid(), code text not null unique, discount_percent numeric(5,2) check(discount_percent>0 and discount_percent<=100), active boolean not null default true, expires_at timestamptz);
create table public.banners (id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text, link text, active boolean not null default true, created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.digital_deliveries enable row level security; alter table public.coupons enable row level security; alter table public.banners enable row level security;
create policy "public read active products" on public.products for select using(active=true);
create policy "public read categories" on public.categories for select using(true);
create policy "public read active banners" on public.banners for select using(active=true);
create policy "user reads own profile" on public.profiles for select using(auth.uid()=id);
create policy "user updates own profile" on public.profiles for update using(auth.uid()=id);
create policy "user reads own orders" on public.orders for select using(auth.uid()=user_id);
create policy "user reads own order items" on public.order_items for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "user reads own payments" on public.payments for select using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=auth.uid()));
create policy "user reads own deliveries" on public.digital_deliveries for select using(auth.uid()=user_id);
insert into public.categories(name,slug) values ('Games','games'),('Assinaturas','assinaturas'),('IA & Tecnologia','ia-tecnologia'),('Design','design'),('Discord','discord'),('Entretenimento','entretenimento') on conflict do nothing;
